const COLUMNS = 'id, school_id, report_type, template_name, title, academic_year_id, term_id, generated_by, generated_by_name, generated_at, report_period_start, report_period_end, student_id, student_name, class_id, class_name, subject_id, subject_name, report_data, visibility, status, approvals, export_formats, distribution_list, created_at';

/** Everything in a school. */
export function listForSchool(schoolId) {
  return rows(
    supabase.from('reports').select(COLUMNS).eq('school_id', schoolId)
      .order('created_at', { ascending: false }),
    'reports.listForSchool',
  );
}

export function get(id) {
  return maybeOne(supabase.from('reports').select(COLUMNS).eq('id', id), 'reports.get');
}

/**
 * Equality filters, for call sites that don't have a named query yet.
 *
 * `where({ school_id, status })` maps each key to `.eq()`; an array value
 * becomes `.in()` and null becomes `.is(null)`. Prefer adding a named
 * function above when the same filter shows up more than once.
 */
export function where(filters = {}, { order, ascending = false, limit } = {}) {
  let q = supabase.from('reports').select(COLUMNS);
  for (const [key, value] of Object.entries(filters)) {
    if (value === undefined) continue;
    if (value === null) q = q.is(key, null);
    else if (Array.isArray(value)) q = q.in(key, value);
    else q = q.eq(key, value);
  }
  if (order) q = q.order(order, { ascending });
  if (limit) q = q.limit(limit);
  return rows(q, 'reports.where');
}

export function create(record) {
  return one(supabase.from('reports').insert(record).select(COLUMNS), 'reports.create');
}

export function update(id, patch) {
  return one(
    supabase.from('reports').update(patch).eq('id', id).select(COLUMNS),
    'reports.update',
  );
}

export function remove(id) {
  return none(supabase.from('reports').delete().eq('id', id), 'reports.remove');
}
